Translate("esES", "azuregos", {
	title = "Azuregos",
	subtitle = "Guardián de las costas arcanas",
	found = "Los bosques del sur de Azshara",
	hint = [=[Busque al gran dragón azul en los bosques del sur. No vaya solo.]=],
	allegiance = "Vuelo Azul",
	sections = {
		{
			title = "Resumen",
			text = [=[Azuregos es un gran dragón azul que vigila el sur de {link:azshara}Azshara{/link}. Las costas de aquí son ricas en magia antigua, y las ruinas todavía guardan las reliquias de los Altonato. Azuregos está aquí para mantenerlas lejos de manos mortales. No oculta lo que es. Advertirá a los intrusos que se marchen, y luego luchará contra ellos.]=],
		},
		{
			title = "Importancia",
			text = [=[El Vuelo Azul siempre ha guardado la magia del mundo de quienes harían mal uso de ella. Que un dragón tan poderoso como Azuregos mantenga su puesto en {link:azshara}Azshara{/link} dice mucho de lo que puede estar oculto aquí. Algunos susurran que en estos bosques podrían haberse hallado los mismísimos legendarios Viales de la Eternidad.

Los buscadores de tesoros que se agolpan en Azshara, elfos de sangre, {link:naga}naga{/link}, goblins y archimagos por igual, vienen todos por la misma magia que él guarda. Tarde o temprano, cada uno de ellos tendrá que vérselas con el dragón.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Guarda los tesoros mágicos de {link:azshara}Azshara{/link} contra todo el que llega.
• Estudia las costas ricas en magia, buscando lo que la {link:great-sundering}Fractura{/link} dejó atrás.
• Dracónidos azules, señores del maná y tejedores de magia de su vuelo vigilan la tierra bajo su mirada.]=],
		},
		{
			title = "Sin registro",
			text = [=[Ninguna crónica registra cuándo llegó Azuregos a {link:azshara}Azshara{/link}, ni qué guarda exactamente. Se dice que los dragones azules han vigilado las ruinas de {link:ruins-of-eldarath}Eldarath{/link} durante muchas generaciones, pero nadie sabe decir si Azuregos ha estado entre ellos desde el principio.]=],
		},
	},
	bonds = {
		{ id = "queen-azshara", name = "Reina Azshara", note = "la reina cuyas reliquias guarda" },
	},
})

